// Surtidores de gasolina (modelo 3D): carcasa + pantalla siempre, mangueras solo de cerca
static void draw_pump_at(float x, float z, float a)
{
    static const float pc[3][3] = { { 70.f, 74.f, 84.f }, { 26.f, 26.f, 28.f }, { 205.f, 46.f, 44.f } };   // pantalla / manguera / carcasa
    float dx = x - px, dz = z - pz, d2 = dx * dx + dz * dz;
    int near = d2 < 7.0f * 7.0f, nt = near ? PUMP_NT : PUMP_NA, nv = near ? PUMP_NV : PUMP_NVA;   // mangueras solo de cerca (menos triangulos = mas fps)
    static V vv[PUMP_NV];
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    float ca = cosf(a), sa = sinf(a);
    for (int i = 0; i < nv; i++) {
        float lx = (float)pump_v[i][0] * 0.001f, lz = (float)pump_v[i][2] * 0.001f;
        vv[i] = mk(x + lx * ca + lz * sa, (float)pump_v[i][1] * 0.001f, z - lx * sa + lz * ca, white, 0.0f);
    }
    for (int k = 0; k < nt; k++) {
        const unsigned short *t = pump_t[k];
        const float *c = pc[t[3]];
        float sh = (float)t[4] / 255.0f;
        V v[3];
        for (int j = 0; j < 3; j++) {
            v[j] = vv[t[j]];
            v[j].r *= c[0] * sh; v[j].g *= c[1] * sh; v[j].b *= c[2] * sh;
        }
        tri_cam(v[0], v[1], v[2]);
    }
}
static void draw_pumps(void)
{
    if (cur_layer != 0 && !climbing) return;
    static const float pp[2][2] = { { 231.5f, 312.0f }, { 236.5f, 312.0f } };
    for (int i = 0; i < 2; i++)
        if (in_view(pp[i][0], pp[i][1], 1.5f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) draw_pump_at(pp[i][0], pp[i][1], PI_F * 0.5f);
}

// ---------------- Super Market (la casa de enfrente de la gasolinera): fachada con letrero de neon ----------------
static void neon_letter(char ch, float cx, float yb, const float *col, float emit, float z, float w, float h, float th)
{
    const float hz = th * 0.47f, ym = yb + h * 0.5f, yt = yb + h;
    int m = 0;                                  // a=1 arriba, b=2 sup.der, c=4 inf.der, d=8 abajo, e=16 inf.izq, f=32 sup.izq, g=64 medio
    switch (ch) {
    case 'S': m = 1 | 32 | 64 | 4 | 8; break;
    case 'U': m = 32 | 16 | 8 | 4 | 2; break;
    case 'P': m = 1 | 2 | 32 | 16 | 64; break;
    case 'E': m = 1 | 32 | 16 | 64 | 8; break;
    case 'R': m = 1 | 2 | 32 | 16 | 64; break;
    case 'M': m = 32 | 16 | 2 | 4; break;
    case 'A': m = 1 | 2 | 4 | 16 | 32 | 64; break;
    case 'K': m = 32 | 16; break;
    case 'T': m = 1; break;
    case 'C': m = 1 | 32 | 16 | 8; break;
    case 'N': m = 32 | 16 | 2 | 4; break;
    case 'B': m = 32 | 16 | 8 | 4 | 64; break;       // como una b minuscula de display
    }
    float lx = cx + w * 0.5f - th * 0.5f, rx = cx - w * 0.5f + th * 0.5f;   // la fachada mira al sur: quien la ve tiene su izquierda en +x
    if (m & 1)  box_rot(cx, z, 0, 0, 0, w * 0.5f, hz, yt - th, yt, col, emit);
    if (m & 64) box_rot(cx, z, 0, 0, 0, w * 0.5f, hz, ym - th * 0.5f, ym + th * 0.5f, col, emit);
    if (m & 8)  box_rot(cx, z, 0, 0, 0, w * 0.5f, hz, yb, yb + th, col, emit);
    if (m & 32) box_rot(lx, z, 0, 0, 0, th * 0.5f, hz, ym, yt, col, emit);
    if (m & 16) box_rot(lx, z, 0, 0, 0, th * 0.5f, hz, yb, ym, col, emit);
    if (m & 2)  box_rot(rx, z, 0, 0, 0, th * 0.5f, hz, ym, yt, col, emit);
    if (m & 4)  box_rot(rx, z, 0, 0, 0, th * 0.5f, hz, yb, ym, col, emit);
    if (ch == 'T') box_rot(cx, z, 0, 0, 0, th * 0.5f, hz, yb, yt, col, emit);
    static const float rs[3][2] = { { 0.40f, 0.40f }, { 0.65f, 0.22f }, { 0.90f, 0.05f } };     // patas en escalera (R, K)
    if (ch == 'R' || ch == 'K') {
        for (int i = 0; i < 3; i++) {
            float px_ = (ch == 'R') ? (cx + w * 0.5f - w * rs[i][0]) : (cx + w * 0.5f - w * (0.35f + 0.3f * (float)i));
            float py_ = yb + h * rs[i][1] + th * 0.5f;
            box_rot(px_, z, 0, 0, 0, th * 0.55f, hz, py_ - th * 0.5f, py_ + th * 0.5f, col, emit);
            if (ch == 'K') {                    // diagonal superior
                float py2 = ym + (ym - py_) + th * 0.0f;
                box_rot(px_, z, 0, 0, 0, th * 0.55f, hz, py2 - th * 0.5f, py2 + th * 0.5f, col, emit);
            }
        }
    }
    if (ch == 'N') {
        static const float ns[3][2] = { { 0.30f, 0.72f }, { 0.50f, 0.50f }, { 0.70f, 0.28f } };
        for (int i = 0; i < 3; i++) {
            float py_ = yb + h * ns[i][1];
            box_rot(cx + w * 0.5f - w * ns[i][0], z, 0, 0, 0, th * 0.55f, hz, py_ - th * 0.5f, py_ + th * 0.5f, col, emit);
        }
    }
    if (ch == 'M') {
        static const float ms[3][2] = { { 0.28f, 0.78f }, { 0.5f, 0.55f }, { 0.72f, 0.78f } };
        for (int i = 0; i < 3; i++) {
            float py_ = yb + h * ms[i][1];
            box_rot(cx + w * 0.5f - w * ms[i][0], z, 0, 0, 0, th * 0.55f, hz, py_ - th * 0.5f, py_ + th * 0.5f, col, emit);
        }
    }
}



// ---------------- Cabana: porche con letrero colgante, linternas, postigos, lena y macetas ----------------
static void draw_cabin(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(64.0f, 270.0f, 20.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
    static const float wood[3] = { 70.f, 45.f, 28.f }, plank[3] = { 110.f, 75.f, 45.f }, stone[3] = { 112.f, 108.f, 104.f };
    static const float amber[3] = { 255.f, 170.f, 60.f }, glassc[3] = { 150.f, 200.f, 220.f }, green[3] = { 40.f, 100.f, 72.f };
    static const float logE[2][3] = { { 175.f, 128.f, 82.f }, { 150.f, 106.f, 66.f } };
    static const float lant[3] = { 255.f, 205.f, 120.f }, black[3] = { 30.f, 30.f, 34.f }, mat[3] = { 125.f, 42.f, 42.f };
    static const float pot[3] = { 150.f, 72.f, 46.f }, leaf[3] = { 48.f, 120.f, 60.f };
    static const float fl[4][3] = { { 220.f, 50.f, 60.f }, { 240.f, 200.f, 60.f }, { 235.f, 120.f, 170.f }, { 250.f, 250.f, 250.f } };
    const float zf = 276.0f;
    // zocalo de piedra a los lados de la puerta, vigas en esquinas y bajo el alero
    box_rot(54.0f, zf + 0.15f, 0, 0, 0, 6.0f, 0.15f, 0.0f, 0.5f, stone, 0.0f);
    box_rot(72.0f, zf + 0.15f, 0, 0, 0, 8.0f, 0.15f, 0.0f, 0.5f, stone, 0.0f);
    box_rot(48.0f, zf + 0.1f, 0, 0, 0, 0.32f, 0.32f, 0.0f, 3.1f, wood, 0.0f);
    box_rot(80.0f, zf + 0.1f, 0, 0, 0, 0.32f, 0.32f, 0.0f, 3.1f, wood, 0.0f);
    box_rot(64.0f, zf + 0.12f, 0, 0, 0, 16.2f, 0.16f, 2.8f, 3.1f, wood, 0.0f);
    box_rot(64.0f, 277.45f, 0, 0, 0, 17.6f, 0.1f, 2.8f, 3.12f, wood, 0.0f);              // tabla del alero
    // ventana de enfrente (x 70): marco, postigos verdes y jardinera con flores
    box_rot(70.0f, zf + 0.06f, 0, 0, 0, 1.12f, 0.06f, 2.2f, 2.38f, wood, 0.0f);
    box_rot(70.0f, zf + 0.1f, 0, 0, 0, 1.15f, 0.12f, 0.88f, 1.02f, plank, 0.0f);
    box_rot(71.07f, zf + 0.06f, 0, 0, 0, 0.07f, 0.06f, 1.0f, 2.2f, wood, 0.0f);
    box_rot(68.93f, zf + 0.06f, 0, 0, 0, 0.07f, 0.06f, 1.0f, 2.2f, wood, 0.0f);
    box_rot(72.0f, zf + 0.1f, 0, 0, 0, 0.42f, 0.05f, 1.0f, 2.4f, green, 0.0f);
    box_rot(68.0f, zf + 0.1f, 0, 0, 0, 0.42f, 0.05f, 1.0f, 2.4f, green, 0.0f);
    box_rot(70.0f, zf + 0.4f, 0, 0, 0, 1.1f, 0.22f, 0.5f, 0.82f, plank, 0.0f);
    for (int i = 0; i < 5; i++) box_rot(69.2f + 0.4f * (float)i, zf + 0.4f, 0, 0, 0, 0.14f, 0.14f, 0.82f, 1.12f, (i & 1) ? fl[i % 4] : leaf, 0.0f);
    // el mismo toque en la ventana del lado este (x 80, z 254)
    box_rot(80.06f, 254.0f, 1.5708f, 0, 0, 1.12f, 0.06f, 2.2f, 2.38f, wood, 0.0f);
    box_rot(80.1f, 252.4f, 1.5708f, 0, 0, 0.42f, 0.05f, 1.0f, 2.4f, green, 0.0f);
    box_rot(80.1f, 255.6f, 1.5708f, 0, 0, 0.42f, 0.05f, 1.0f, 2.4f, green, 0.0f);
    // letrero colgante bajo el techo del porche: "CABANA" en ambar brillante
    box_rot(60.2f, 284.3f, 0, 0, 0, 0.04f, 0.04f, 2.45f, 2.75f, black, 0.0f);
    box_rot(63.8f, 284.3f, 0, 0, 0, 0.04f, 0.04f, 2.45f, 2.75f, black, 0.0f);
    box_rot(62.0f, 284.3f, 0, 0, 0, 2.3f, 0.07f, 1.55f, 2.45f, wood, 0.0f);
    box_rot(62.0f, 284.37f, 0, 0, 0, 2.3f, 0.02f, 1.55f, 1.6f, amber, 0.8f);
    box_rot(62.0f, 284.37f, 0, 0, 0, 2.3f, 0.02f, 2.4f, 2.45f, amber, 0.8f);
    static const char txt[7] = "CABANA";
    for (int i = 0; i < 6; i++) {
        float e = 1.0f;
        if (i == 3 && sinf(t * 19.0f) + sinf(t * 6.1f) > 1.7f) e = 0.15f;
        neon_letter(txt[i], 62.0f - ((float)i - 2.5f) * 0.72f, 1.72f, amber, e, 284.45f, 0.5f, 0.6f, 0.09f);
    }
    // linternas en las esquinas del porche (parpadean suave como una llama)
    float fk = 0.85f + 0.15f * sinf(t * 11.0f + 2.0f);
    for (int s = 0; s < 2; s++) {
        float lx = s ? 67.7f : 56.3f;
        box_rot(lx, 283.85f, 0, 0, 0, 0.05f, 0.18f, 2.0f, 2.05f, black, 0.0f);
        box_rot(lx, 284.0f, 0, 0, 0, 0.14f, 0.14f, 1.62f, 1.98f, lant, 0.9f * fk);
        box_rot(lx, 284.0f, 0, 0, 0, 0.19f, 0.19f, 1.98f, 2.04f, black, 0.0f);
        box_rot(lx, 284.0f, 0, 0, 0, 0.19f, 0.19f, 1.56f, 1.62f, black, 0.0f);
    }
    // leña apilada junto a la ventana
    box_rot(75.8f, zf + 0.5f, 0, 0, 0, 1.25f, 0.34f, 0.0f, 1.0f, wood, 0.0f);
    for (int r = 0; r < 3; r++)
        for (int c = 0; c < 6; c++)
            box_rot(74.75f + 0.42f * (float)c, zf + 0.86f, 0, 0, 0, 0.17f, 0.03f, 0.1f + 0.3f * (float)r, 0.36f + 0.3f * (float)r, logE[(r + c) & 1], 0.0f);
    // felpudo y macetas a los lados de la puerta
    box_rot(62.0f, zf + 1.3f, 0, 0, 0, 1.0f, 0.5f, 0.0f, 0.03f, mat, 0.0f);
    for (int s = 0; s < 2; s++) {
        float px2 = s ? 65.6f : 58.4f;
        box_rot(px2, zf + 0.7f, 0, 0, 0, 0.3f, 0.3f, 0.0f, 0.45f, pot, 0.0f);
        box_rot(px2, zf + 0.7f, 0, 0, 0, 0.26f, 0.26f, 0.45f, 1.05f, leaf, 0.0f);
        box_rot(px2, zf + 0.7f, 0, 0, 0, 0.12f, 0.12f, 1.05f, 1.2f, fl[s ? 1 : 0], 0.0f);
    }
    (void)glassc;
}

static void draw_supermarket(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(234.0f, 296.0f, 12.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
    static const float dark[3] = { 22.f, 22.f, 30.f }, pink[3] = { 255.f, 60.f, 170.f }, cyan[3] = { 60.f, 230.f, 255.f };
    static const float stone[3] = { 205.f, 205.f, 210.f }, glass[3] = { 140.f, 190.f, 215.f }, frame[3] = { 40.f, 40.f, 46.f };
    static const float red[3] = { 200.f, 40.f, 44.f }, white[3] = { 235.f, 235.f, 238.f }, green[3] = { 70.f, 255.f, 130.f };
    const float zf = 296.0f;
    // letrero (panel oscuro sobre la fachada) con marco de neon
    box_rot(234.0f, 296.2f, 0, 0, 0, 9.8f, 0.2f, 3.2f, 5.3f, dark, 0.0f);
    box_rot(234.0f, 296.5f, 0, 0, 0, 9.8f, 0.06f, 5.2f, 5.3f, pink, 1.0f);
    box_rot(234.0f, 296.5f, 0, 0, 0, 9.8f, 0.06f, 3.2f, 3.3f, pink, 1.0f);
    box_rot(224.3f, 296.5f, 0, 0, 0, 0.1f, 0.06f, 3.2f, 5.3f, pink, 1.0f);
    box_rot(243.7f, 296.5f, 0, 0, 0, 0.1f, 0.06f, 3.2f, 5.3f, pink, 1.0f);
    // letras de neon: "SUPER MARKET" (la E de SUPER y la K parpadean)
    static const char txt[13] = "SUPER MARKET";
    for (int i = 0; i < 12; i++) {
        if (txt[i] == ' ') continue;
        float e = 1.0f;
        if (i == 3 && sinf(t * 23.0f) + sinf(t * 7.3f) > 1.55f) e = 0.12f;
        if (i == 11 && sinf(t * 17.0f + 1.0f) + sinf(t * 5.1f) > 1.6f) e = 0.12f;
        neon_letter(txt[i], 234.0f - ((float)i - 5.5f) * 1.5f, 3.65f, i < 5 ? pink : cyan, e, 296.58f, 1.1f, 1.2f, 0.15f);
    }
    // toldo rayado sobre la puerta
    for (int i = 0; i < 10; i++)
        box_rot(229.5f + (float)i, 297.2f, 0, 0, 0, 0.5f, 1.2f, 2.55f, 2.7f, (i & 1) ? white : red, 0.0f);
    box_rot(234.0f, 298.45f, 0, 0, 0, 5.0f, 0.06f, 2.3f, 2.7f, red, 0.0f);
    // "ABIERTO" no cabe: un cartel verde pequeno junto a la puerta
    box_rot(237.7f, zf + 0.1f, 0, 0, 0, 0.5f, 0.05f, 1.5f, 1.9f, green, 0.9f);
    // vitrinas con marco a cada lado de la puerta
    for (int s = 0; s < 2; s++) {
        float cx = s ? 240.0f : 228.0f;
        box_rot(cx, zf + 0.04f, 0, 0, 0, 3.15f, 0.04f, 0.65f, 2.75f, frame, 0.0f);
        box_rot(cx, zf + 0.09f, 0, 0, 0, 3.0f, 0.04f, 0.8f, 2.6f, glass, 0.2f);
        box_rot(cx, zf + 0.14f, 0, 0, 0, 0.06f, 0.04f, 0.8f, 2.6f, frame, 0.0f);
        box_rot(cx - 1.5f, zf + 0.14f, 0, 0, 0, 0.06f, 0.04f, 0.8f, 2.6f, frame, 0.0f);
        box_rot(cx + 1.5f, zf + 0.14f, 0, 0, 0, 0.06f, 0.04f, 0.8f, 2.6f, frame, 0.0f);
        box_rot(cx, zf + 0.14f, 0, 0, 0, 3.0f, 0.04f, 1.6f, 1.66f, frame, 0.0f);
    }
    // pilastras en las esquinas y zocalo
    box_rot(224.0f, zf + 0.15f, 0, 0, 0, 0.4f, 0.4f, 0.0f, 3.25f, stone, 0.0f);
    box_rot(244.0f, zf + 0.15f, 0, 0, 0, 0.4f, 0.4f, 0.0f, 3.25f, stone, 0.0f);
    box_rot(234.0f, zf + 0.05f, 0, 0, 0, 10.0f, 0.06f, 0.0f, 0.45f, red, 0.0f);
    // cajas de fruta junto a la entrada (decoracion)
    box_rot(229.0f, 298.4f, 0, 0, 0, 0.8f, 0.45f, 0.0f, 0.6f, (const float[3]){ 150.f, 105.f, 60.f }, 0.0f);
    box_rot(239.0f, 298.4f, 0, 0, 0, 0.8f, 0.45f, 0.0f, 0.6f, (const float[3]){ 150.f, 105.f, 60.f }, 0.0f);
    box_rot(229.0f, 298.4f, 0, 0, 0, 0.7f, 0.35f, 0.6f, 0.75f, (const float[3]){ 200.f, 60.f, 40.f }, 0.0f);
    box_rot(239.0f, 298.4f, 0, 0, 0, 0.7f, 0.35f, 0.6f, 0.75f, (const float[3]){ 230.f, 190.f, 50.f }, 0.0f);
}

