// rocas y farolas (modelos OBJ)
static void draw_rocks(void)
{
    if (cur_layer != 0 && !climbing) return;
    float lim = fminf(draw_lim, (gfx_pd[gfx] * rd_k));
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    static V vv[RK_NV];
    for (int n = 0; n < (int)(sizeof(rk_pos) / sizeof(rk_pos[0])); n++) {
        const float *q = rk_pos[n];
        float S = (q[2] / 4.6f + q[3] / 6.2f) * 0.5f * 0.01f;
        if (!in_view(q[0], q[1], q[2] * 2.0f + 0.5f, lim)) continue;
        float ya = q[0] * 12.9898f + q[1] * 78.233f, ca = cosf(ya), sa = sinf(ya);
        for (int i = 0; i < RK_NV; i++) {
            float lx = (float)RK_v[i][0] * S, lz = (float)RK_v[i][2] * S;
            vv[i] = mk(q[0] + lx * ca + lz * sa, (float)RK_v[i][1] * S - 0.03f, q[1] - lx * sa + lz * ca, white, 0.0f);
        }
        float k = 1.15f;
        for (int t = 0; t < RK_NT; t++) {
            const unsigned short *tt = RK_t[t];
            float sh = (float)tt[4] / 255.0f;
            V v[3];
            for (int j = 0; j < 3; j++) {
                v[j] = vv[tt[j]];
                v[j].r *= q[4] * k * sh; v[j].g *= q[5] * k * sh; v[j].b *= q[6] * k * sh;
            }
            tri_cam(v[0], v[1], v[2]);
        }
    }
}

static void draw_lamps(void)
{
    if (cur_layer != 1 && !climbing) return;
    float lim = fminf(draw_lim, (gfx_pd[gfx] * rd_k));
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    static V vv[LP_NV];
    for (int n = 0; n < (int)(sizeof(lp_pos) / sizeof(lp_pos[0])); n++) {
        const float *q = lp_pos[n];
        if (!in_view(q[0], q[1], 1.0f, lim)) continue;
        const float S = 0.00036f;
        for (int i = 0; i < LP_NV; i++)
            vv[i] = mk(q[0] + (float)LP_v[i][0] * S, SEWER_Y + (float)LP_v[i][1] * S, q[1] + (float)LP_v[i][2] * S, white, 0.0f);
        for (int t = 0; t < LP_NT; t++) {
            const unsigned short *tt = LP_t[t];
            float sh = (float)tt[4] / 255.0f;
            V v[3];
            for (int j = 0; j < 3; j++) {
                v[j] = vv[tt[j]];
                if (tt[3] == 1) { v[j].r = q[2]; v[j].g = q[3]; v[j].b = q[4]; }
                else { v[j].r *= 52.f * sh; v[j].g *= 48.f * sh; v[j].b *= 44.f * sh; }
            }
            tri_cam(v[0], v[1], v[2]);
        }
    }
}

static void draw_props(float t)
{
    for (int i = 0; i < NPROP; i++) {
        const Prop *p = &props[i];
        if (p->layer != cur_layer && !climbing) continue;
        float rad = fmaxf(p->hx, p->hz) * 1.45f + 0.6f;
        if (!in_view(p->x, p->z, rad, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) continue;
        float col[3] = { (float)p->r, (float)p->g, (float)p->b };
        if (p->type == 0 && p->emit == 0.0f && p->x > 192.0f && p->x < 196.2f && p->z > 176.0f && p->z < 180.0f &&
            p->y1 - p->y0 < 0.2f && p->y0 < 34.0f) {      // antena: menos travesanos (la torre y su alcance de dibujado siguen igual)
            float ddx = p->x - px, ddz = p->z - pz;
            if (ddx * ddx + ddz * ddz > 64.0f && !(fabsf(p->y0 - 5.0f) < 0.1f || fabsf(p->y0 - 15.0f) < 0.1f || fabsf(p->y0 - 25.0f) < 0.1f)) continue;
        }
        switch (p->type) {
        case 0:
            if (p->hx > 4.0f || p->hz > 4.0f) {                 // muro/valla muy largo: se dibuja en tramos de ~4 m (uno solo se deformaba al acercarte)
                int alongx = p->hx >= p->hz;
                float half = alongx ? p->hx : p->hz;
                int ns = (int)ceilf(half / 2.0f);
                float sh = half / (float)ns, ca = cosf(p->a), sa = sinf(p->a);
                float lim = fminf(draw_lim, (gfx_pd[gfx] * rd_k));
                for (int k = 0; k < ns; k++) {
                    float off = -half + sh * (2.0f * (float)k + 1.0f);
                    float lx = alongx ? off : 0.0f, lz = alongx ? 0.0f : off;
                    float wx = p->x + lx * ca + lz * sa, wz = p->z - lx * sa + lz * ca;
                    if (!in_view(wx, wz, sh * 1.5f + 0.6f, lim)) continue;
                    box_rot(p->x, p->z, p->a, lx, lz, alongx ? sh : p->hx, alongx ? p->hz : sh, p->y0, p->y1, col, p->emit);
                }
            } else box_rot(p->x, p->z, p->a, 0, 0, p->hx, p->hz, p->y0, p->y1, col, p->emit);
            break;
        case 2: box_rot(p->x, p->z, p->a, 0, 0, p->hx, p->hz, p->y0, p->y1, col,
                        p->emit * (0.75f + 0.25f * sinf(t * 17.0f + p->x))); break;
        case 1: roof_rot(p->x, p->z, p->a, p->hx, p->hz, p->y0, p->y1, col); break;
        case 3: pyr_rot(p->x, p->z, p->hx, p->y0, p->y1, col); break;
        }
    }
}

