        gsKit_prim_sprite(gsGlobal, 24.0f, 66.0f, 34.0f, 67.0f, 16777020, GS_SETREG_RGBAQ(90, 70, 45, 0x80, 0));
        gsKit_prim_sprite(gsGlobal, 24.0f, 69.0f, 31.0f, 70.0f, 16777020, GS_SETREG_RGBAQ(90, 70, 45, 0x80, 0));
