static void menu_dim(void)       // oscurece la pantalla (fondo de pausa)
{
    gsKit_set_primalpha(gsGlobal, BLEND_STD, 0);
    gsGlobal->PrimAlphaEnable = GS_SETTING_ON;
    gsKit_prim_sprite(gsGlobal, 0.0f, 0.0f, W, H, 16777200, GS_SETREG_RGBAQ(0, 0, 0, ba(86), 0));
    gsGlobal->PrimAlphaEnable = GS_SETTING_OFF;
}

static void render_game(float t, int moving, int near_ladder, int notes)
{
    if (dance_id < 0 || state != 0 || climbing || map_open || dance_open) { dance_cam = 0; render_game_inner(t, moving, near_ladder, notes); return; }
    // camara en tercera persona: delante de ti, mirandote
    float spx = px, spz = pz, sfx_ = fx, sfz_ = fz, srx = rx, srz = rz, scy = cam_y, scp = cpitch, ssp = spitch, sroll_c = cam_rc, sroll_s = cam_rs;
    float dir_x = sinf(yaw), dir_z = cosf(yaw), D = 4.6f;
    while (D > 1.2f && blocked(px + dir_x * D, pz + dir_z * D, 0.4f)) D -= 0.3f;
    px = spx + dir_x * D; pz = spz + dir_z * D;
    fx = -dir_x; fz = -dir_z; rx = -cosf(yaw); rz = sinf(yaw);
    cpitch = cosf(0.10f); spitch = sinf(0.10f); cam_rc = 1.0f; cam_rs = 0.0f;
    cam_y = foot_y + jump_h + 2.0f;
    dance_cam = 1;
    dance_px = spx; dance_pz = spz;
    render_game_inner(t, 0, -1, notes);
    dance_cam = 0;
    px = spx; pz = spz; fx = sfx_; fz = sfz_; rx = srx; rz = srz; cam_y = scy; cpitch = scp; spitch = ssp; cam_rc = sroll_c; cam_rs = sroll_s;
}

// Dibuja un cuadro de juego: pantalla completa (1 jugador) o dividida (2 jugadores)
static void render_frame(float t, int paused)
{
    int notes = notes_got[0] + notes_got[1] + notes_got[2];
    if (num_players < 2 || state != 0 || net_online) {   // 1 jugador, online, jumpscare o final: pantalla completa
        int pi = (num_players == 2 && state == 1) ? js_victim : (net_online ? net_local : 0);
        view_full();
        int vi = (num_players == 2) ? view_of(pi) : pi;
        pl_view_alt = vi != pi ? pi : -1;
        player_load(vi);
        render_game(t, paused ? 0 : p_moving, paused ? -1 : p_near, notes);
        pl_view_alt = -1;
        view_full();
        return;
    }
    int hh = (int)(SH * 0.5f);                           // J1 arriba, J2 abajo
    for (int i = 0; i < 2; i++) {
        int vi = view_of(i);
        pl_view_alt = vi != i ? i : -1;
        player_load(vi);
        if (i == 0) view_set(0.0f, 0.0f, SW, (float)(hh - 1));
        else        view_set(0.0f, (float)(hh + 1), SW, SH - (float)(hh + 1));
        render_game(t, paused ? 0 : p_moving, paused ? -1 : p_near, notes);
    }
    pl_view_alt = -1;
    view_full();
    gsKit_prim_sprite(gsGlobal, 0.0f, (float)(hh - 1), SW, (float)(hh + 1), 16777000, GS_SETREG_RGBAQ(0, 0, 0, 0x80, 0));   // linea divisoria
}

static int pad2_ready(void)                              // hay un control en el puerto 2?
{
    int s = padGetState(1, 0);
    return s == PAD_STATE_STABLE || s == PAD_STATE_FINDCTP1;
}
static int pad2_warn;

static void start_game(int players)
{
    num_players = players;
    if (players == 2) padSetMainMode(1, 0, PAD_MMODE_DUALSHOCK, PAD_MMODE_LOCK);
    reset_game();
    spec_mode = spec_pending; spec_pending = 0;
    screen = SC_PLAY;
}

